package com.portfolio.features.portfolio.entity; import jakarta.persistence.*; import java.util.*; import lombok.*; @Entity @Table(name="portfolio_sections") @Getter @Setter @NoArgsConstructor public class PortfolioSection{@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="portfolio_id") private Portfolio portfolio;@Column(name="section_type") private String sectionType;private int position;private boolean enabled;private String layout;private String alignment;private String background;private String spacing;}
